export const PREVIEW_SAMPLE_QUESTIONS_BY_EXAM: Record<PreviewSampleExamId, PreviewSampleQuestion[]> = {
  analytical_reasoning: [
    { id: "gemini-code-1779396266238", prompt: "Five seats are labelled 1–5 from left to right. Each seat is assigned exactly one unique symbol from the set: ★, ●, ■, △, ▶. Use the constraints below to determine which seat contains the symbol ▶.", options: ["Seat 1", "Seat 3", "Seat 4", "Seat 5"], correctIndex: 0, level: 1, stimulus_type: "text", stimulus: {"text": "Constraints:\n1. ★ is assigned to Seat 2.\n2. ● is located immediately to the right of ★.\n3. ■ is located in a higher-numbered seat than ▶.\n4. △ is assigned to Seat 5.", "structured_solution": "Constraint 1 explicitly fixes ★ at Seat 2. Constraint 2 establishes that ● is immediately to the right of ★, which assigns ● to Seat 3. Constraint 4 explicitly fixes △ at Seat 5. At this step of the deduction chain, only Seat 1 and Seat 4 remain unassigned. Constraint 3 dictates that ■ must occupy a higher-numbered seat than ▶. Comparing the available coordinates (Seat 1 and Seat 4), ■ must be placed in Seat 4, which forces ▶ into Seat 1."} },
    { id: "gemini-code-1779396735666", prompt: "Five positions are labelled 1–5 from left to right. Each position holds exactly one unique symbol from the set: ★, ●, ■, △, ▷. Use the constraints to determine which position holds the symbol ▷.", options: ["Position 1", "Position 2", "Position 3", "Position 5"], correctIndex: 0, level: 2, stimulus_type: "text", stimulus: {"text": "Constraints:\n1. If ★ is in an odd-numbered position, then ● is immediately to its right.\n2. ■ is in position 4.\n3. △ is somewhere to the left of ■.\n4. ★ is not in position 5.\n5. ▷ is not adjacent to ■.\n6. ● is in a higher-numbered position than ▷.", "structured_solution": "Constraint 2 fixes ■ in position 4. Constraint 5 dictates that ▷ cannot be adjacent to ■, eliminating positions 3 and 5, which leaves only positions 1 and 2 open for ▷. Constraint 6 states that ● must occupy a higher position number than ▷. Now, test the hypothesis of placing ▷ in position 2: if ▷ is in position 2, the remaining available slots for ★, ●, and △ are positions 1, 3, and 5. Constraint 3 requires △ to sit left of position 4, forcing △ into position 1 or 3. Constraint 4 prevents ★ from occupying position 5. If ★ is placed in position 1 (odd), constraint 1 requires ● to be in position 2, which is blocked by ▷. If ★ is placed in position 3 (odd), ● must be in position 4, which is blocked by ■. Thus, placing ▷ in position 2 leaves no mathematically valid slot for ★ under the conditional constraint. By elimination, ▷ must occupy position 1. This yields the unique valid sequence: ▷ in 1, ★ in 2, △ in 3, ■ in 4, and ● in 5."} },
    { id: "gemini-code-1779396900349", prompt: "Five boxes are labelled 1–5 from left to right. Each box contains exactly one unique shape from the set: ○, ■, △, ★, ●. Use the constraints below to determine which box contains the symbol ★.", options: ["Box 1", "Box 3", "Box 4", "Box 5"], correctIndex: 0, level: 2, stimulus_type: "text", stimulus: {"text": "Constraints:\n1. ■ is in Box 2.\n2. ○ is located somewhere to the right of ★.\n3. △ is immediately to the left of ●.\n4. ★ is not in Box 4.\n5. ○ is not in Box 5.", "structured_solution": "Constraint 1 permanently fixes ■ in Box 2. Constraint 3 dictates that △ must sit immediately to the left of ●, creating a locked adjacent block [△, ●]. Given that Box 2 is occupied by ■, this adjacent block cannot occupy positions (1,2) or (2,3). Therefore, the block [△, ●] must sit at either positions (3,4) or (4,5). Test the hypothesis of placing the block at positions (3,4), meaning △ is in Box 3 and ● is in Box 4. This leaves Box 1 and Box 5 open for the remaining symbols, ★ and ○. Constraint 4 states that ★ cannot be in Box 4 (already occupied by ●), and Constraint 2 states that ○ must sit somewhere to the right of ★. If ★ occupies Box 5, there is no slot available to its right for ○. Thus, ★ would be forced into Box 1, placing ○ in Box 5. However, this directly violates Constraint 5, which states ○ cannot be in Box 5. Therefore, the block [△, ●] cannot occupy positions (3,4). By elimination, the block [△, ●] must occupy positions (4,5). This leaves Box 1 and Box 3 open for ★ and ○. To satisfy Constraint 2 (○ must sit to the right of ★), ★ must be assigned to Box 1, forcing ○ into Box 3."} },
    { id: "gemini-code-1779395907956", prompt: "Four boxes are labelled 1–4 from left to right. Each box has a different colour. Use the clues to determine which box is green.", options: ["Box 1", "Box 2", "Box 3", "Box 4"], correctIndex: 3, level: 1, stimulus_type: "text", stimulus: {"text": "Clues:\n1. Box 3 is red.\n2. The blue box is immediately to the left of the red box.\n3. The green box is not Box 1.", "structured_solution": "According to Clue 1, Box 3 is red. Clue 2 states that the blue box is immediately to the left of the red box, which places the blue box at Box 2. This leaves Box 1 and Box 4 unassigned. Clue 3 specifies that the green box is not Box 1, which logically eliminates Box 1 and forces the green box to be Box 4."} },
    { id: "gemini-code-1779396283286", prompt: "Four boxes are labelled 1–4 from left to right. Each box holds exactly one unique shape from the set: ★, ●, ■, △. Use the constraints to determine which box holds the symbol ★.", options: ["Box 1", "Box 2", "Box 3", "Box 4"], correctIndex: 3, level: 1, stimulus_type: "text", stimulus: {"text": "Constraints:\n1. ● is in Box 2.\n2. ★ is located somewhere to the right of ■.\n3. △ is not in Box 4.\n4. ■ is not in Box 1.", "structured_solution": "Constraint 1 explicitly fixes ● in Box 2. Constraint 4 states that ■ cannot be in Box 1; since Box 2 is already occupied by ●, ■ must occupy either Box 3 or Box 4. Constraint 2 establishes that ★ is located somewhere to the right of ■. If ■ were placed in Box 4, there would be no remaining coordinates available to its right to accommodate ★. Therefore, ■ must be assigned to Box 3. This leaves Box 1 and Box 4 open. Since ★ must sit to the right of ■ (Box 3), ★ must be placed in Box 4. By elimination, △ is assigned to Box 1, which satisfies Constraint 3."} },
    { id: "gemini-code-1779396750134", prompt: "Analyze the alternating progression rule that governs Format A. Apply that exact same structural rule to determine the missing sequence elements in Format B.", options: ["★★★ , ★★★★", "★ , ★★", "★★★ , ★★", "★★ , ★"], correctIndex: 1, level: 2, stimulus_type: "text", stimulus: {"text": "Format A (Numeric Source): 5 → 10 → 7 → 14 → 11\nFormat B (Symbolic Target): ★ → ★★ → ? → ?", "structured_solution": "Evaluating Format A reveals an alternating arithmetic operational loop across consecutive steps: on odd-numbered transitions, the value doubles ($\times 2$); on even-numbered transitions, it decrements by 3 ($-3$). This establishes the path: $5 \times 2 = 10$, $10 - 3 = 7$, $7 \times 2 = 14$, $14 - 3 = 11$. Transferring this structure to Format B, the values track the absolute count of the ★ symbols, starting at 1. Step 1 executes the doubling rule: $1 \times 2 = 2$, yielding ★★, which perfectly matches the stimulus stem. Step 2 requires subtracting 3 ($2 - 3 = -1$). However, because symbol density counts cannot drop below a baseline minimum, a conditional floor boundary applies: when a subtraction step drops the count below 1, it defaults to a minimum state value of 1 shape (★). Step 3 then resumes the odd transition phase by doubling the current value: $1 \times 2 = 2$, which outputs ★★. Therefore, the two missing items are ★ followed by ★★."} },
    { id: "gemini-code-1779396738948", prompt: "Apply the following three transformation rules in sequence to the input string to determine the final output string.", options: ["★ ▲ ★ ▲ ■", "■ ▲ ★ ▲ ★", "○ ▲ ★ ▲ ■", "★ ▲ ○ ▲ ★"], correctIndex: 1, level: 2, stimulus_type: "text", stimulus: {"text": "Transformation Rules:\nRule 1: Swap the positions of the first and last symbols.\nRule 2: If the middle symbol is ▲, replace all instances of ■ with ★. Otherwise, replace all instances of ○ with ★.\nRule 3: Reverse the entire resulting sequence.\n\nInput String: [■, ▲, ○, ▲, ○]", "structured_solution": "Step 1: Apply Rule 1 by swapping the first symbol (■) and the last symbol (○). The intermediate string becomes [○, ▲, ○, ▲, ■]. Step 2: Evaluate the conditional requirement of Rule 2 on this intermediate string. The middle (3rd) symbol is currently ○. Because it is not ▲, the 'otherwise' branch is triggered, requiring all instances of ○ to be replaced with ★. Applying this substitution transforms the string into [★, ▲, ★, ▲, ■]. Step 3: Apply Rule 3 by fully reversing this sequence. Reading the elements from right to left yields the final output string: [■, ▲, ★, ▲, ★]."} },
    { id: "gemini-code-1779396275903", prompt: "The sequence below contains two independent patterns running simultaneously at alternating positions. Which symbol logically completes the sequence?", options: ["★", "●", "○", "■"], correctIndex: 1, level: 1, stimulus_type: "text", stimulus: {"text": "Sequence: △, ★, ○, ●, ■, ★, △, ___", "structured_solution": "To resolve the sequence, it must be separated by index parity into odd and even sub-streams. The odd-positioned items (1st, 3rd, 5th, 7th) follow a repeating geometric shape cycle: △ → ○ → ■ → △. The even-positioned items (2nd, 4th, 6th, 8th) follow an independent alternating pattern: ★ → ● → ★ → ___. The missing slot is located at position 8, which belongs to the even sub-stream. Continuing the alternating pattern after the position 6 marker (★) yields the symbol ●."} },
    { id: "gemini-code-1779396285767", prompt: "Apply the given transformation rules in sequence to the input string. Apply Rule 1 first, then apply Rule 2 to the resulting string.", options: ["● ★ ○ ■", "■ ★ ○ ●", "■ ★ ○ ▲", "● ★ ○ ■"], correctIndex: 1, level: 1, stimulus_type: "text", stimulus: {"text": "Rule 1: Swap the positions of the first and last symbols.\nRule 2: Replace every instance of ▲ with ●.\n\nInput String: [▲, ★, ○, ■]", "structured_solution": "Applying Rule 1 requires swapping the first symbol (▲) and the last symbol (■). This spatial manipulation transforms the input string into [■, ★, ○, ▲]. Next, applying Rule 2 requires replacing every instance of ▲ with ● within this modified array. Since ▲ is now located at the final position, it converts to ●, yielding the final output string [■, ★, ○, ●]."} },
    { id: "gemini-code-1779395917739", prompt: "Which sequence does NOT follow the same structural rule as the other three?", options: ["○ ○ ●", "△ △ ▲", "■ ■ ●", "▷ ▷ ▶"], correctIndex: 2, level: 1, stimulus_type: "text", stimulus: {"text": "An array of four three-symbol strings.", "structured_solution": "In options A, B, and D, the structural rule dictates that two identical outline shapes are followed by the solid, filled version of that exact same geometric shape (circles in A, triangles in B, right-pointers in D). Option C breaks this rule because the initial outline shapes are squares (■), but the trailing filled shape is a circle (●)."} },
    { id: "gemini-code-1779395920911", prompt: "Apply the given transformation rule to the input sequence to determine the correct output sequence.", options: ["○ △ ★ ■", "○ △ ■ ★", "■ △ ★ ○", "★ ○ △ ■"], correctIndex: 1, level: 1, stimulus_type: "text", stimulus: {"text": "Rule: Swap the positions of the first and last symbols.\nInput Sequence: [★, △, ■, ○]", "structured_solution": "The rule explicitly dictates an exchange of positions between the first element (★) and the fourth/last element (○). The intermediate elements in the second and third positions (△ and ■) must remain exactly where they are. Applying this rule transforms [★, △, ■, ○] into [○, △, ■, ★]."} },
    { id: "gemini-code-1779389138264", prompt: "Which sequence does NOT follow the same structural rule as the other three?", options: ["○ △ ■", "△ ■ ⬠", "■ ⬠ ⬡", "⬠ ■ ⬡"], correctIndex: 3, level: 1, stimulus_type: "text", stimulus: {"text": "An array of four three-element symbol strings.", "structured_solution": "In options A, B, and C, the number of sides belonging to each geometric symbol increases sequentially from left to right. In option A, the progression is 1 (or 0) to 3 to 4. In option B, it is 3 to 4 to 5. In option C, it is 4 to 5 to 6. Option D violates this rule because the side count decreases from 5 (pentagon) to 4 (square) before increasing to 6 (hexagon)."} },
    { id: "gemini-code-1779396914599", prompt: "Which symbol logically completes the repeating block progression?", options: ["○", "■", "△", "★"], correctIndex: 1, level: 2, stimulus_type: "text", stimulus: {"text": "Sequence: △, ○, ○, ■, ○, ○, ■, ■, ○, ○, ■, ■, ■, ○, ○, ■, ■, ■, ■, ○, ○, ___", "structured_solution": "The sequence is governed by a recursive block structure with an incremental tracking rule. The initial symbol (△) acts as a standalone opening delimiter that never recurs. Stripping this marker reveals a series of structured item blocks separated by constant boundaries. Each block contains exactly two open circles (○, ○) followed by an expanding run of solid squares (■). Evaluating the blocks sequentially shows: Block 1 has 1 square (○○■); Block 2 has 2 squares (○○■■); Block 3 has 3 squares (○○■■■); Block 4 has 4 squares (○○■■■■). Following this established incremental rule, Block 5 must consist of exactly two circles followed by five squares. The characters immediately preceding the blank are the two starting circles of Block 5. Therefore, the missing entry must be the first square element of the new block run, yielding ■."} },
    { id: "gemini-code-1779389147816", prompt: "Which symbol logically completes the sequence?", options: ["○", "●", "△", "▲"], correctIndex: 1, level: 1, stimulus_type: "text", stimulus: {"text": "Sequence: △, ▲, ○, ●, △, ▲, ○, ___", "structured_solution": "The sequence tracks two independent, alternating attributes: shape type and fill state. The shape type follows a repeating pairs pattern: two triangles followed by two circles (Triangle, Triangle, Circle, Circle). The fill state alternates perfectly between open and solid filled (Open, Filled, Open, Filled). The seventh item is an open circle, which means the eighth item must maintain the circle shape identity while transitioning to a solid filled state, yielding a solid circle (●)."} },
    { id: "gemini-code-1779396817846", prompt: "Apply the following three transformation rules in sequence to the input string to determine the final output string. Apply Rule 1 first, then Rule 2, then Rule 3.", options: ["◁ ★ ○ ■ △", "◁ ★ ○ ■ ◁", "△ ■ ○ ★ ◁", "▲ ★ ○ ■ △"], correctIndex: 0, level: 2, stimulus_type: "text", stimulus: {"text": "Transformation Rules:\nRule 1: Swap the positions of the first and last symbols.\nRule 2: Replace every instance of ▲ with ◁.\nRule 3: Reverse the entire resulting sequence.\n\nInput String: [▲, ■, ○, ★, △]", "structured_solution": "Step 1: Apply Rule 1 by swapping the first symbol (▲) and the last symbol (△). The string transitions into the intermediate state [△, ■, ○, ★, ▲]. Step 2: Apply Rule 2 by replacing every instance of ▲ with ◁. In the current intermediate state, ▲ resides exclusively at the final index position (Position 5). Substituting this character yields the modified string [△, ■, ○, ★, ◁]. Step 3: Apply Rule 3 by fully reversing this sequence. Reading the elements backward from right to left converts [△, ■, ○, ★, ◁] into the final output string: [◁, ★, ○, ■, △]."} },
    { id: "gemini-code-1779396272820", prompt: "Apply the given rules in sequence to the input string. What is the final output string?\n\nRule 1: Swap the positions of the first and last symbols.\nRule 2: Replace every instance of ▲ with ★.", options: ["◁ ■ ○ △ ★ ★", "★ ■ ○ △ ▲ ◁", "★ ■ ○ △ ★ ◁", "◁ ■ ○ △ ★ ▲"], correctIndex: 0, level: 1, stimulus_type: "text", stimulus: {"text": "Input String: [▲, ■, ○, △, ▲, ◁]", "structured_solution": "Applying Rule 1 (swap the first symbol ▲ and the last symbol ◁) transforms the input string into [◁, ■, ○, △, ▲, ▲]. Note that the original first symbol ▲ is now located at the very end of the string. Next, applying Rule 2 (replace every instance of ▲ with ★) target-scans the modified string. The symbols at positions 5 and 6 are both ▲, so both transform into ★. This yields the final output string [◁, ■, ○, △, ★, ★]."} },
    { id: "gemini-code-1779396294533", prompt: "Analyze the operational growth rule running through Pattern 1. Apply that exact same structural rule to determine what completes Pattern 2.", options: ["△△△△△△△△ (8 triangles)", "△△△△△△△△△ (9 triangles)", "△△△△△△△△△△ (10 triangles)", "△△△△△△△△△△△△ (12 triangles)"], correctIndex: 2, level: 1, stimulus_type: "text", stimulus: {"text": "Pattern 1 (Numeric Source Sequence): 3 → 6 → 9 → 12\nPattern 2 (Symbolic Target Sequence): △ → △△△△ → △△△△△△△ → ?", "structured_solution": "In Pattern 1, analyzing the progression shows that each subsequent value increases by a constant arithmetic difference of +3 (3 + 3 = 6, 6 + 3 = 9, 9 + 3 = 12). The structural rule is constant arithmetic addition. Transitioning to Pattern 2, we evaluate the shape density counts per step: 1 triangle → 4 triangles → 7 triangles. Checking the difference between these steps confirms a constant increase of +3 (1 + 3 = 4, 4 + 3 = 7). Applying this structural addition rule to the third step requires adding 3 triangles to 7, which yields a total of 10 triangles."} },
    { id: "gemini-code-1779396400487", prompt: "Which sequence does NOT follow the same structural rules as the other three?", options: ["△ ● △ ●", "■ ○ ■ ○", "▲ ★ ▲ ★", "◁ ▶ ◁ ●"], correctIndex: 3, level: 1, stimulus_type: "text", stimulus: {"text": "An array of four four-symbol sequences.", "structured_solution": "Options A, B, and C adhere to two coordinated constraints: they consist of exactly two distinct symbols, and those symbols alternate in a perfect ABAB pattern (where position 1 matches position 3, and position 2 matches position 4). Option D breaks this rule; while its first and third symbols match (◁), its second symbol (▶) and fourth symbol (●) are completely different, disrupting the required structural alternation."} },
    { id: "gemini-code-1779396269388", prompt: "Three of the sequences below follow the exact same structural rules. Which sequence is the exception and does NOT belong with the others?", options: ["△ ● ■ ○", "■ ○ △ ●", "○ △ ● ■", "● ■ △ ○"], correctIndex: 3, level: 1, stimulus_type: "text", stimulus: {"text": "An array of four four-symbol strings.", "structured_solution": "The matching options are governed by two simultaneous constraints: completeness (containing the symbols △, ●, ■, and ○ exactly once) and strict positional alternation based on geometric edge profiles: Angular (straight-edged: △, ■) versus Round (curved-edged: ○, ●). In option A, the pattern maps as Angular-Round-Angular-Round. Option B maps as Angular-Round-Angular-Round. Option C maps as Round-Angular-Round-Angular. Option D breaks this rule because it groups two round symbols together at the borders and two angular symbols together in the interior (Round-Angular-Angular-Round), failing the structural alternation requirement."} },
    { id: "gemini-code-1779389113571", prompt: "Which sequence does NOT follow the same structural rule as the other three?", options: ["△ ○ ○ △", "■ ★ ★ ■", "▲ ● ● ▲", "○ △ ○ △"], correctIndex: 3, level: 1, stimulus_type: "text", stimulus: {"text": "An array of four symbolic sequences.", "structured_solution": "Options A, B, and C are palindromes that possess mirror symmetry, meaning they read exactly the same forwards and backwards (the first symbol matches the fourth, and the second symbol matches the third). Option D breaks this structural rule because reversing '○ △ ○ △' results in '△ ○ △ ○', which is not identical to the original order."} },
    { id: "gemini-code-1779395911005", prompt: "Which sequence does NOT follow the same structural rule as the other three?", options: ["△ ○ △", "■ ★ ■", "▲ ● ▲", "○ △ ■"], correctIndex: 3, level: 1, stimulus_type: "text", stimulus: {"text": "An array of four three-symbol strings.", "structured_solution": "Options A, B, and C follow a specific 'bookend' rule where the first and third symbols in the string are completely identical, creating a symmetrical boundary around a unique center symbol. Option D violates this rule because its first symbol (○) and third symbol (■) do not match."} },
    { id: "gemini-code-1779396743114", prompt: "Three of the non-verbal sequences below follow the exact same underlying structural rule. Which sequence is the exception and does NOT belong with the others?", options: ["△ ▷ ▽ ◁ △", "■ ★ ■ ★ ■", "○ ▲ ▼ ▲ ○", "▶ ● ◀ ● ▶"], correctIndex: 2, level: 2, stimulus_type: "text", stimulus: {"text": "An array of four five-symbol strings.", "structured_solution": "The matching options are governed by an advanced, compound conditional taxonomy. First, all options must form a valid positional palindrome (the string reads identically forwards and backwards). Second, a conditional transformation applies to adjacent elements: if a symbol has a directional orientation (triangles, arrows), it must rotate exactly 90 degrees clockwise at each successive position; if a symbol is symmetric/non-directional (circles, squares, stars), it must alternate with a different symmetric shape. Option A consists of oriented triangles rotating 90 degrees clockwise at each step (Up, Right, Down, Left, Up). Option B consists of non-directional shapes alternating perfectly (Square, Star, Square, Star, Square). Option D coordinates both cleanly: directional arrows advance 180 degrees across symmetric intervals, maintaining a valid clockwise coordinate step. Option C breaks this system: the directional triangle ▲ (Up) transitions directly to ▼ (Down), which represents a 180-degree flip rather than the mandatory 90-degree clockwise rotation."} },
    { id: "gemini-code-1779396815079", prompt: "Three of the non-verbal sequences below follow the exact same structural rule. Which sequence is the exception and does NOT belong with the others?", options: ["△ ▷ ▽ ◁", "○ ○ ○ ○", "▲ ▶ ▼ ◀", "★ ★ ★ ★"], correctIndex: 1, level: 2, stimulus_type: "text", stimulus: {"text": "An array of four four-symbol arrays.", "structured_solution": "The matching options (A, C, and D) are governed by a strict structural progression rule: each successive symbol represents a single geometric shape rotated exactly 90 degrees clockwise through four distinct spatial orientations. Option A demonstrates this with an open asymmetric triangle pointing Up, Right, Down, Left. Option C demonstrates this with a solid-filled version of the same triangular rotation sequence. Option D also conforms to this rule; a standard asymmetrical five-pointed star rotated successively by 90 degrees enters unique spatial states at each step. Option B is the absolute structural exception. A perfect circle possesses infinite rotational symmetry, meaning that rotating it by any degree produces an identical visual state. It is impossible for a circle to exhibit a progressive sequence of four distinct rotational orientations; it represents pure flat item repetition rather than active operational transformation."} },
    { id: "gemini-code-1779389145165", prompt: "Each row and each column in the grid follows the same logical rule. Which symbol replaces the question mark?", options: ["△", "★", "●", "○"], correctIndex: 0, level: 1, stimulus_type: "text", stimulus: {"text": "Grid:\n[ △ , ★ , ● ]\n[ ● , △ , ★ ]\n[ ★ , ● , ? ]", "structured_solution": "The grid is structured as a Latin square, where each row and each column must contain exactly one of each unique symbol from the set {△, ★, ●}. The third row currently contains ★ and ●, leaving △ as the missing element. Cross-checking the third column confirms this, as it contains ● and ★, which likewise requires △ to satisfy the rule."} },
    { id: "gemini-code-1779396291434", prompt: "The sequence below is formed by interleaving two independent patterns. Which symbol logically replaces the question mark?", options: ["△", "●", "○", "▲"], correctIndex: 2, level: 1, stimulus_type: "text", stimulus: {"text": "Sequence: △, ●, ▲, ●, ○, △, ●, ▲, ●, ○, △, ●, ▲, ●, ?", "structured_solution": "The sequence operates by splitting elements across odd and even index positions. The odd-positioned entries (1st, 3rd, 5th, 7th, 9th, 11th, 13th, 15th) follow a repeating three-symbol geometric shape cycle: △ → ▲ → ○ → △ → ▲ → ○. The even-positioned entries (2nd, 4th, 6th, 8th, 10th, 12th, 14th) follow a constant static pattern where every element is invariably ●. The target position is the 15th element, which belongs to the odd index sub-stream. Following the established loop after the 13th element (▲), the next shape in the odd cycle is ○."} },
    { id: "gemini-code-1779396746415", prompt: "The symbols in the 3×3 grid follow a complex logical rule across rows and down columns. Which symbol correctly replaces the question mark?", options: ["△", "■", "○", "★"], correctIndex: 2, level: 2, stimulus_type: "text", stimulus: {"text": "Grid:\n[ △ , ○ , ■ ]\n[ ○ , ■ , △ ]\n[ ■ , △ , ? ]", "structured_solution": "The grid operates on a set-completion constraint intersected with a conditional structural property. Across both rows and columns, the placement of the third symbol is dependent on the morphological properties of the leading symbol. If the first symbol in a vector consists exclusively of straight edges (△, ■), the terminal cell must be the unique missing element from the total set pool {△, ○, ■}. If the leading symbol contains curved paths (○), a secondary priority order determines the coordinate mapping. Examining Row 3, the vector commences with ■ (straight edges), which activates the direct set-omission rule. The absent element from the pair [■, △] is ○. Cross-checking Column 3 confirms this convergence: it features [■, △] running top-to-bottom, which likewise dictates ○ to satisfy the orthogonal constraint."} },
    { id: "gemini-code-1779396908133", prompt: "Apply the following three transformation rules in sequence to the input string to determine the final output string. Apply Rule 1 first, then Rule 2, then Rule 3.", options: ["▲ ★ ○ ◁ △", "▲ ★ ○ ★ △", "▲ ★ ○ ◁ ◁", "△ ★ ○ ■ ▲"], correctIndex: 1, level: 2, stimulus_type: "text", stimulus: {"text": "Transformation Rules:\nRule 1: Swap the positions of the first and last symbols.\nRule 2: If the string contains more than one ▲, replace every instance of ■ with ◁. Otherwise, replace every instance of ■ with ★.\nRule 3: Reverse the entire resulting sequence.\n\nInput String: [▲, ■, ○, ★, △]", "structured_solution": "Step 1: Apply Rule 1 by swapping the first symbol (▲) and the last symbol (△). The string transitions into the intermediate state [△, ■, ○, ★, ▲]. Step 2: Evaluate the conditional requirement of Rule 2 on this intermediate string. Count the instances of ▲ present in this modified array. There is only one ▲ (located at the final index position). Because the count does not exceed one, the 'otherwise' branch is triggered, requiring every instance of ■ to be replaced with ★. Applying this substitution transforms the string into [△, ★, ○, ★, ▲]. Step 3: Apply Rule 3 by fully reversing this sequence. Reading the elements backward from right to left converts [△, ★, ○, ★, ▲] into the final output string: [▲, ★, ○, ★, △]."} },
    { id: "gemini-code-1779396911414", prompt: "The symbols in the 3×3 grid follow a complex logical rule across rows and down columns. Which symbol correctly replaces the question mark?", options: ["▲", "▽", "■", "●"], correctIndex: 1, level: 2, stimulus_type: "text", stimulus: {"text": "Grid:\n[ ▲ ,  ▽ ,  ■ ]\n[ ▽ ,  ■ ,  ▲ ]\n[ ■ ,  ▲ ,   ? ]", "structured_solution": "The grid operates on a set-completion constraint intersected with an orientation priority rule. Across rows and columns, the vector transformations depend on the edge characteristics of the leading symbol. If a vector starts with an upward-oriented shape (▲), it triggers a forward cyclic loop (▲ → ▽ → ■). If it starts with a square (■), it defaults to an ascending vertex count rule. Examining Row 3, the line begins with ■, which requires cell 2 and cell 3 to fall into ascending vertex count order (▲ with 3 points, followed by ▽ with 3 points, where up-pointing prioritizes down-pointing). Cross-checking Column 3 confirms this exact convergence: it features ■ in cell 1 followed by ▲ in cell 2, which requires ▽ to satisfy the column set closure rule. Both axes intersect perfectly at ▽."} },
    { id: "gemini-code-1779396278805", prompt: "Analyze the operational growth rule in Pattern 1. Apply that exact same structural rule to complete Pattern 2 within its distinct symbolic format.", options: ["■■■■■", "■■■■■■", "■■■■■■■■", "■■■■■■■■■■"], correctIndex: 2, level: 1, stimulus_type: "text", stimulus: {"text": "Pattern 1 (Numeric Source): 3 → 6 → 12 → 24\nPattern 2 (Symbolic Target): ■ → ■■ → ■■■■ → ?", "structured_solution": "In Pattern 1, analyzing the progression shows that each subsequent value is generated by multiplying the preceding value by 2 (3 × 2 = 6, 6 × 2 = 12, 12 × 2 = 24). The structural rule is geometric growth by a constant doubling factor. Transitioning to Pattern 2, we map the symbol counts per step: 1 square → 2 squares → 4 squares. Applying the exact same doubling rule to the third step requires multiplying 4 by 2, which yields 8 squares (■■■■■■■■)."} },
    { id: "gemini-code-1779396288783", prompt: "The symbols in the grid follow distinct logical rules across rows and down columns. Which symbol completes the grid?", options: ["■■", "▰▰", "■", "▢"], correctIndex: 0, level: 1, stimulus_type: "text", stimulus: {"text": "Grid:\n[ △ ,  ▲ ,  ▲▲ ]\n[ ○ ,  ● ,  ●● ]\n[ ■ ,  ■ ,   ?  ]", "structured_solution": "The matrix is governed by two independent feature rules. The horizontal row rule determines geometric shape identity: Row 1 contains triangles, Row 2 contains circles, and Row 3 contains squares. The vertical column rule determines the compound fill and density state: Column 1 items are single hollow shapes, Column 2 items are single solid-filled shapes, and Column 3 items are double solid-filled versions of that row's shape. Following the Row 3 shape property (square) and the Column 3 density property (double solid-filled), the missing entry must be two solid squares side-by-side (■■)."} },
    { id: "gemini-code-1779389142320", prompt: "Apply the given rule to the input sequence to determine the correct output sequence.\n\nRule: Cycle every symbol forward one step in this exact order: ■ → △ → ★ → ■", options: ["■ △ ■ △", "■ △ ★ △", "★ ■ △ ■", "△ ★ ■ ★"], correctIndex: 1, level: 1, stimulus_type: "text", stimulus: {"text": "Input Sequence: [★, ■, △, ■]", "structured_solution": "According to the cyclic transformation rule: ★ maps to ■, ■ maps to △, and △ maps to ★. Applying this systematically to each element of the input sequence [★, ■, △, ■] yields the output sequence [■, △, ★, △]."} },
    { id: "gemini-code-1779395923854", prompt: "Each row and each column in the grid follows the same structural rule. Which symbol replaces the question mark?", options: ["■", "○", "△", "▲"], correctIndex: 2, level: 1, stimulus_type: "text", stimulus: {"text": "Grid:\n[ △ , ■ , ○ ]\n[ ○ , △ , ■ ]\n[ ■ , ○ , ? ]", "structured_solution": "The grid operates on a row and column constraint where each horizontal line and vertical line must contain exactly one unique instance of each symbol from the set {△, ■, ○}. Examining the third row reveals it already contains ■ and ○, meaning the missing symbol must be △. Cross-checking the third column confirms this choice, as it contains ○ and ■, which likewise demands △ to complete the column set."} },
    { id: "gemini-code-1779396811138", prompt: "Five symbols - ○, ■, △, ★, ● - are placed in positions 1–5 from left to right. Use the constraints below to determine which symbol occupies Position 4.", options: ["■", "★", "△", "○"], correctIndex: 0, level: 2, stimulus_type: "text", stimulus: {"text": "Constraints:\n1. ★ is located somewhere to the right of ■.\n2. ○ is immediately to the left of △.\n3. ● is in Position 1.\n4. ■ is not in Position 2.\n5. ○ is not in Position 4.\n6. ★ is in an odd-numbered position.", "structured_solution": "Constraint 3 permanently fixes ● in Position 1, leaving positions 2–5 open for the remaining elements {■, ○, △, ★}. Constraint 2 requires ○ and △ to occupy adjacent slots in that exact left-to-right order (the cluster [○, △]). Looking at the remaining slots, this cluster can theoretically sit at (2,3), (3,4), or (4,5). Constraint 5 explicitly states that ○ cannot occupy Position 4, which immediately eliminates the (4,5) placement option. Now, test the hypothesis of placing the cluster at (3,4), meaning ○ is in Position 3 and △ is in Position 4: this leaves positions 2 and 5 open for ■ and ★. Constraint 4 dictates that ■ cannot be in Position 2, forcing ■ into Position 5 and ★ into Position 2. However, this arrangement directly violates Constraint 1, which states ★ must sit to the right of ■ (since index 2 is left of index 5). Thus, the (3,4) placement is invalid. By elimination, the [○, △] cluster must occupy positions (2,3). This leaves positions 4 and 5 open for ■ and ★. Constraint 6 specifies that ★ must reside in an odd-numbered position, forcing ★ into Position 5 and leaving Position 4 for ■. This final sequence (●, ○, △, ■, ★) seamlessly satisfies all parameters."} },
  ],
  verbal_reasoning: [
    { id: "gemini-code-1779397474047", prompt: "The author claims that agricultural automation increases long-term farm yields. Which of the following findings from the passage provides the direct evidence supporting this specific claim?", options: ["Manual harvesting allows for a more careful selection of crops during the harvest phase.", "Automated tractors are equipped with advanced multispectral sensors to assess health.", "Fields using automated sensor systems produce fifteen percent more grain per acre over a decade.", "Farms can eliminate human picking errors by replacing traditional workers with machinery."], correctIndex: 2, level: 1, stimulus_type: "text", stimulus: {"text": "Passage: While manual harvesting allows for careful selection, automated tractors equipped with multispectral sensors can instantly assess crop health across vast fields. By deploying these machines, farms eliminate human picking errors and apply targeted nutrients precisely where plants are failing. Data collected over a decade reveals that fields using these automated sensor systems consistently produce fifteen percent more grain per acre than fields managed entirely by hand.", "evidence_spans": [{"text": "Data collected over a decade reveals that fields using these automated sensor systems consistently produce fifteen percent more grain per acre than fields managed entirely by hand.", "role": "supports_correct_answer", "sentence_index": 2}], "external_knowledge_required": false, "cultural_specificity": "low", "structured_solution": "The author's specific claim is that agricultural automation increases long-term farm yields. Sentence 3 provides the direct empirical evidence validating this claim by citing a decade of data showing a measurable, quantifiable output increase: a fifteen percent increase in grain per acre for automated fields compared to manual ones. Options B and D describe the mechanisms of automation (sensors and error reduction) but do not present the actual yield data. Option A describes a benefit of manual harvesting, which opposes the target claim."} },
    { id: "gemini-code-1779397477944", prompt: "Based strictly on the explicit facts provided in the passage, which of the following statements must be true?", options: ["Ravi's grandmother prefers factory-manufactured winter clothing over hand-knit items.", "Ravi did not receive a hand-knit scarf from his grandmother during the first week of this winter.", "The local shop where the scarf was purchased specializes in traditional woolen winter garments.", "Ravi's grandmother will be completely unable to knit scarves for him in future winters."], correctIndex: 1, level: 1, stimulus_type: "text", stimulus: {"text": "Passage: Ravi's grandmother has hand-knit a new woolen scarf for him during the first week of every winter for the past ten years. This year, due to sudden joint stiffness, she was unable to hold her traditional metal knitting needles. On Ravi's annual visit in December, she presented him with a factory-manufactured scarf that she purchased at a local shop.", "evidence_spans": [{"text": "This year, due to sudden joint stiffness, she was unable to hold her traditional metal knitting needles.", "role": "supports_correct_answer", "sentence_index": 1}, {"text": "On Ravi's annual visit in December, she presented him with a factory-manufactured scarf that she purchased at a local shop.", "role": "supports_correct_answer", "sentence_index": 2}], "external_knowledge_required": false, "cultural_specificity": "low", "structured_solution": "The passage states that this year the grandmother was unable to hold her knitting needles and instead presented Ravi with a purchased, factory-manufactured scarf. Therefore, it is a logically necessary inference that Ravi did not receive a hand-knit scarf from his grandmother this winter. Option A is incorrect because her purchase was due to physical limitation, not a stated preference. Options C and D are unsupported speculations that project beyond the strict boundaries of the text."} },
    { id: "gemini-code-1779397481395", prompt: "The argument in the passage relies on which of the following unstated assumptions?", options: ["Migratory birds are unable to build secure nests in low-lying bushes or alternative park structures.", "The construction of the civic parking structure will take more than six months to complete.", "Environmental workers intend to plant new tall trees once the parking structure is fully built.", "Regional biologists have tracked the exact nesting habits of these migratory birds for over a decade."], correctIndex: 0, level: 1, stimulus_type: "text", stimulus: {"text": "Passage: Migratory birds require dense canopy coverage to build secure nests during the spring breeding season. Last summer, environmental workers cleared out all the tall trees in the central park to clear space for a civic parking structure. Consequently, regional biologists predict that no migratory birds will nest in the central park this coming spring.", "evidence_spans": [{"text": "Migratory birds require dense canopy coverage to build secure nests during the spring breeding season.", "role": "supports_correct_answer", "sentence_index": 0}, {"text": "Last summer, environmental workers cleared out all the tall trees in the central park to clear space for a civic parking structure.", "role": "supports_correct_answer", "sentence_index": 1}], "external_knowledge_required": false, "cultural_specificity": "low", "structured_solution": "The argument states that migratory birds require dense canopy coverage from tall trees to nest, and that the tall trees are now gone. From this, it concludes that no birds will nest in the park this spring. This conclusion is valid only if the birds cannot simply adapt by nesting in other areas of the park, such as bushes or structures. Therefore, the argument implicitly assumes that migratory birds cannot build secure nests in low-lying bushes or alternative park structures. Options B, C, and D introduce external elements or historical context that are completely irrelevant to the core logical link between tree removal and the absence of nesting."} },
    { id: "gemini-code-1779397484497", prompt: "Which of the following statements, if true, best explains the unexpected finding described in the passage?", options: ["Several local factories closed down permanently immediately after the new emissions caps went into effect.", "The city experienced a massive population influx of commuters driving high-emission vehicles during that same year.", "Public health clinics reported a minor shortage of respiratory medications during the peak winter months.", "The industrial air pollution caps were heavily praised by environmental activists throughout the region."], correctIndex: 1, level: 1, stimulus_type: "text", stimulus: {"text": "Passage: A major manufacturing city recently implemented strict emissions caps on all local factories, resulting in a documented forty percent drop in industrial air pollution. However, public health data collected during the first year under these caps revealed that the overall rate of respiratory hospital admissions in the city did not decrease at all.", "evidence_spans": [{"text": "implementing strict emissions caps on all local factories, resulting in a documented forty percent drop in industrial air pollution.", "role": "supports_correct_answer", "sentence_index": 0}, {"text": "However, public health data collected during the first year under these caps revealed that the overall rate of respiratory hospital admissions in the city did not decrease at all.", "role": "supports_correct_answer", "sentence_index": 1}], "external_knowledge_required": false, "cultural_specificity": "low", "structured_solution": "The passage presents a paradox: industrial emissions dropped by forty percent, but citywide respiratory hospital admissions remained unchanged. Option B resolves this discrepancy by introducing an alternative, compensating source of air pollution: a massive influx of high-emission commuter vehicles during that same period. Option A would explain a further drop in pollution but does not explain why health rates failed to improve. Option C touches on treatment shortages but does not explain the root cause of the steady admission rates. Option D describes public reactions, which has no bearing on the physical metrics."} },
    { id: "gemini-code-1779397487411", prompt: "Which statement best describes the structural relationship between the first sentence and the final sentence of the passage?", options: ["The first sentence presents an irrelevant baseline detail, while the final sentence refutes it with new empirical evidence.", "The first sentence introduces an anecdotal observation, while the final sentence states a verified historical fact.", "The first sentence defines a critical biological mechanism, while the final sentence states a logical consequence of disrupting that mechanism.", "The first sentence outlines a controversial hypothesis, while the final sentence summarizes the scientific consensus around it."], correctIndex: 2, level: 1, stimulus_type: "text", stimulus: {"text": "Passage: Underground fungi networks function as an essential biological highway by transporting vital phosphorus between distant plant roots. Because isolated forest trees cannot absorb sufficient soil minerals on their own, they depend entirely on these fungal links to survive. Consequently, the widespread destruction of underground fungal ecosystems will inevitably lead to a severe collapse of the above-ground forest canopy.", "evidence_spans": [{"text": "Underground fungi networks function as an essential biological highway by transporting vital phosphorus between distant plant roots.", "role": "supports_correct_answer", "sentence_index": 0}, {"text": "Consequently, the widespread destruction of underground fungal ecosystems will inevitably lead to a severe collapse of the above-ground forest canopy.", "role": "supports_correct_answer", "sentence_index": 2}], "external_knowledge_required": false, "cultural_specificity": "low", "structured_solution": "The first sentence establishes the foundational mechanism: underground fungi act as a highway transporting phosphorus between plant roots. The final sentence uses the causal connector 'Consequently' to state the logical outcome of removing that mechanism: the collapse of the forest canopy. Therefore, Option C perfectly describes this structural link. Options A, B, and D mischaracterize the text as containing refutations, anecdotes, or controversies, none of which exist in this objective scientific explanation."} },
    { id: "gemini-code-1779397676415", prompt: "The doctors' conclusion depends on which of the following unstated assumptions?", options: ["Patients who suffer from chronic poor sleep quality generally enjoy reading fiction or narratives.", "Feeling more rested in the morning is the most reliable indicator of an improvement in overall physical health.", "The increased morning restfulness reported by the survey participants was actually caused by the bedtime reading habit rather than an unstated third factor.", "Recommending bedtime reading is more cost-effective for a local clinic than prescribing traditional sleep medications."], correctIndex: 2, level: 2, stimulus_type: "text", stimulus: {"text": "Passage: A recent medical survey found that individuals who read for at least twenty minutes immediately before sleeping reported feeling significantly more rested in the morning. Based on this correlation, doctors at a local clinic have started recommending bedtime reading to patients who suffer from chronic poor sleep quality. The doctors conclude that adopting this simple nighttime habit will directly cause these patients to wake up feeling refreshed and energetic.", "evidence_spans": [{"text": "A recent medical survey found that individuals who read for at least twenty minutes immediately before sleeping reported feeling significantly more rested in the morning.", "role": "supports_correct_answer", "sentence_index": 0}, {"text": "The doctors conclude that adopting this simple nighttime habit will directly cause these patients to wake up feeling refreshed and energetic.", "role": "supports_correct_answer", "sentence_index": 2}], "external_knowledge_required": false, "cultural_specificity": "low", "structured_solution": "The passage describes a classic correlation-to-causation logical leap. The survey establishes a correlation: bedtime reading is linked to feeling rested. The doctors jump to a causal conclusion: reading will *cause* poor sleepers to wake up refreshed. For this causal argument to hold true, the argument must implicitly assume that the correlation is directly causal and not the result of some other common factor (such as readers having a more relaxed lifestyle or avoiding screens). Therefore, it must assume that the restfulness was caused by the reading itself and not an unstated third factor. Option A describes user preferences, which is irrelevant to the causal mechanism. Option B over-generalizes to total physical health, which extends past the argument scope. Option D introduces economic metrics, which are completely outside the text's logic loop."} },
    { id: "gemini-code-1779397679963", prompt: "Which of the following findings, if true, would most seriously weaken the city officials' conclusion?", options: ["The city government spent more money maintaining the new LED streetlights than it had originally budgeted.", "Concurrently with the streetlight installation, the city deployed automated speed-enforcement cameras and increased police patrols on those same arterial roads.", "A survey of local residents revealed that many found the high-intensity LED light to be unpleasantly bright and distracting to house windows.", "The number of daytime traffic accidents on those arterial roads remained completely unchanged during that same twelve-month evaluation period."], correctIndex: 1, level: 2, stimulus_type: "text", stimulus: {"text": "Passage: A city government recently installed high-intensity LED streetlights along several major arterial roads. Since the installation, traffic data compiled over twelve months revealed that the number of nighttime vehicular accidents on those specific roads dropped by exactly thirty percent. City officials concluded that the improved street illumination was the primary driver behind the reduction in accidents, and they now plan to deploy similar LED lighting across all residential streets to lower accident rates citywide.", "evidence_spans": [{"text": "City officials concluded that the improved street illumination was the primary driver behind the reduction in accidents", "role": "supports_correct_answer", "sentence_index": 2}], "external_knowledge_required": false, "cultural_specificity": "low", "structured_solution": "The city officials draw a causal conclusion: the new lights caused the accident drop. To weaken this argument, an option must present an alternative cause that can explain the drop, thereby undercutting the unique role of the streetlights. Option B introduces two powerful alternative variables-speed cameras and increased police patrols-deployed on those exact roads at the exact same time. This makes it impossible to determine if the lights or the law enforcement caused the safety improvement, severely weakening the officials' conclusion. Option A concerns fiscal budgets, which has no logical link to safety metrics. Option C details aesthetic resident complaints, which does not impact the objective crash volume data. Option D shows daytime rates stayed steady, which actually slightly strengthens or preserves the focus on nighttime-specific variables."} },
    { id: "gemini-code-1779397683930", prompt: "The passage argues that integrating natural coastal infrastructure provides superior flood mitigation compared to static artificial options. Which of the following findings from the passage provides the most direct empirical support for this specific claim?", options: ["Concrete sea walls are being built by many low-lying coastal cities to mitigate the threat of rising ocean levels.", "Engineering assessments indicate that artificial concrete barriers are highly susceptible to cracking under prolonged wave impact.", "Field studies demonstrate that restoring native mangrove forests absorbs up to forty percent more kinetic wave energy than traditional concrete walls.", "Thousands of hectares of coastal wetlands continue to be cleared annually to clear room for industrial commercial developments."], correctIndex: 2, level: 2, stimulus_type: "text", stimulus: {"text": "Passage: Many low-lying coastal cities are building massive concrete sea walls to buffer against rising ocean levels. However, engineering assessments indicate that these barriers can crack under prolonged wave impact. Field studies demonstrate that restoring native mangrove forests along vulnerable coastlines absorbs up to forty percent more kinetic wave energy than traditional concrete walls. Furthermore, mangroves organically trap marine sediment, which gradually raises the natural elevation of the shoreline over time. Despite these documented benefits, thousands of hectares of coastal wetlands continue to be cleared annually for industrial commercial developments.", "evidence_spans": [{"text": "Field studies demonstrate that restoring native mangrove forests along vulnerable coastlines absorbs up to forty percent more kinetic wave energy than traditional concrete walls.", "role": "supports_correct_answer", "sentence_index": 2}], "external_knowledge_required": false, "cultural_specificity": "low", "structured_solution": "The specific target claim is that natural infrastructure (mangroves) provides superior flood mitigation compared to artificial infrastructure (sea walls). Sentence 3 provides the direct empirical validation for this claim by presenting a clear comparative finding: restored mangrove forests absorb forty percent more kinetic wave energy than traditional concrete walls. Option B supports a sub-claim regarding the flaws of concrete walls but does not validate the superiority of the natural alternative. Option A describes what cities are currently doing (contextual background), and Option D describes environmental loss, neither of which functions as an empirical premise supporting flood mitigation effectiveness."} },
    { id: "gemini-code-1779397688164", prompt: "Based strictly on the interlocking facts provided in the passage, which of the following statements must be true?", options: ["Deep-sea ecosystems located near hydrothermal vents are highly vulnerable to localized climate fluctuations occurring on the ocean surface.", "The complex animal life discovered near the vents does not depend on solar energy pathways for its survival.", "Giant tube worms and blind shrimp possess specialized visual organs that allow them to navigate in absolute darkness.", "Hydrothermal vents are the most abundant source of organic chemical minerals across the entire global seafloor."], correctIndex: 1, level: 2, stimulus_type: "text", stimulus: {"text": "Passage: For decades, biologists operated under the assumption that the deep ocean floor was entirely devoid of complex animal life due to the complete absence of sunlight. However, oceanographic expeditions in the late 1970s discovered hydrothermal seafloor vents that discharge superheated water dense with chemical minerals. In the immediate vicinity of these vents, researchers documented thriving ecosystems of previously unknown organisms, including giant tube worms and blind shrimp. Crucially, microscopic laboratory analysis confirmed that the primary bacteria forming the baseline food supply for these deep-sea creatures synthesize energy exclusively by processing sulfur compounds from the vent fluid.", "evidence_spans": [{"text": "biologists operated under the assumption that the deep ocean floor was entirely devoid of complex animal life due to the complete absence of sunlight.", "role": "supports_correct_answer", "sentence_index": 0}, {"text": "Crucially, microscopic laboratory analysis confirmed that the primary bacteria forming the baseline food supply for these deep-sea creatures synthesize energy exclusively by processing sulfur compounds from the vent fluid.", "role": "supports_correct_answer", "sentence_index": 3}], "external_knowledge_required": false, "cultural_specificity": "low", "structured_solution": "To find the mandatory inference, we must chain together distinct data points across the passage. The text states that the deep ocean floor receives zero sunlight (Sentence 1), but complex organisms thrive there (Sentence 3). It then specifies that the baseline food supply for these organisms generates energy exclusively by processing sulfur compounds from vent fluid (Sentence 4). Because the entire ecosystem's baseline food supply synthesizes energy from chemicals rather than sunlight, it is a logically necessary deduction that these ecosystems do not depend on solar energy pathways for survival. Option A is an unsupported speculative leak regarding surface climate vulnerability. Option C directly contradicts the description of the shrimp as 'blind.' Option D over-generalizes to global abundance metrics, which are completely absent from the text."} },
    { id: "gemini-code-1779397691961", prompt: "Which of the following historical findings, if true, best reconciles the apparent contradiction described by the regional biologists?", options: ["The logging company paid substantial environmental fines to the Millbrook municipal council after completing their clear-cutting operation.", "The remaining forty percent of the forested hillsides consisted of young saplings that had been planted less than two years prior.", "The logging occurred on hillsides whose bedrock is composed of dense, erosion-resistant granite that does not dissolve into mud or loose silt when exposed to water.", "Local farmers in the valley shifted their cultivation from traditional wet rice paddies to low-water root vegetables during that same monsoon season."], correctIndex: 2, level: 2, stimulus_type: "text", stimulus: {"text": "Passage: The hillsides surrounding the agricultural valley of Millbrook were historic for their dense, ancient forests. Decades of land data showed that even during the heaviest monsoon rains, the rivers feeding the valley remained perfectly crystal clear because the complex tree root systems held the hillside soil firmly in place. Recently, a major logging operation clear-cut sixty percent of these forests. Surprisingly, during the massive monsoon rains that immediately followed the logging, the valley's rivers still remained completely clear and free of mud.", "evidence_spans": [{"text": "the rivers feeding the valley remained perfectly crystal clear because the complex tree root systems held the hillside soil firmly in place.", "role": "supports_correct_answer", "sentence_index": 1}, {"text": "Surprisingly, during the massive monsoon rains that immediately followed the logging, the valley's rivers still remained completely clear and free of mud.", "role": "supports_correct_answer", "sentence_index": 3}], "external_knowledge_required": false, "cultural_specificity": "low", "structured_solution": "The passage presents a causal paradox: trees hold soil, tree removal should cause soil erosion and muddy rivers during a monsoon, yet clear-cutting resulted in zero muddy river water. To resolve this discrepancy, an option must provide an alternative structural explanation for why this specific hillside did not erode when the trees were removed. Option C resolves this perfectly by specifying that the underlying bedrock is erosion-resistant granite, which inherently prevents mud formation regardless of tree cover. Option A deals with financial regulations, which has no bearing on physical soil mechanics. Option B introduces young saplings, which would have weaker root networks and worsen erosion rather than preventing it. Option D discusses crop shifts in the valley floor, which cannot explain the physical properties of water running down from the hillsides above."} },
    { id: "gemini-code-1779397698328", prompt: "On which point do the authors of Passage A and Passage B most clearly disagree?", options: ["Whether students experience psychological stress from dense academic schoolwork.", "Whether classroom instruction plays a role in establishing student learning parameters.", "Whether research linking homework to test scores serves as reliable evidence of homework's intrinsic value.", "Whether schools should continue to utilize standardised testing instruments to measure student baseline ability."], correctIndex: 2, level: 3, stimulus_type: "text", stimulus: {"text": {"passage_a": "Homework is essential for academic success. When students practise concepts at home, they strengthen their understanding and develop self-discipline. Research consistently shows that students who complete homework regularly perform better on standardised tests. Schools that have reduced homework loads have seen declining test scores, suggesting that cutting homework harms learning outcomes.", "passage_b": "Homework in its current form does more harm than good. Excessive assignments leave students stressed and exhausted, reducing their motivation to learn. Studies that link homework to higher test scores often fail to account for other factors, such as family income and access to tutoring. What matters is not the quantity of practice but the quality of classroom instruction."}, "evidence_spans": [{"passage": "A", "text": "Research consistently shows that students who complete homework regularly perform better on standardised tests.", "sentence_index": 2, "role": "establishes_claim"}, {"passage": "B", "text": "Studies that link homework to higher test scores often fail to account for other factors, such as family income and access to tutoring.", "sentence_index": 2, "role": "supports_correct_answer"}], "external_knowledge_required": false, "cultural_specificity": "low", "structured_solution": "Passage A explicitly cites research connecting regular homework completion to higher standardized test scores, treating this empirical correlation as definitive proof of homework's essential value. Passage B directly counters this sub-claim by asserting that these identical studies are methodologically flawed because they fail to account for critical confounding variables such as family income and access to private tutoring. Therefore, the authors fundamentally clash on whether the existing body of research serves as a valid, reliable indicator of homework's effectiveness. Option A represents a one-sided point mentioned only in Passage B. Option B misrepresents Passage A, which never claims classroom teaching is irrelevant. Option D is an off-topic consideration, as neither author challenges the validity of the testing instruments themselves."} },
    { id: "gemini-code-1779397701527", prompt: "Which of the following findings, if true, most seriously weakens the city officials' causal argument?", options: ["Roads in neighbouring municipalities that also installed high-intensity LED streetlights saw a similar decrease in nighttime accidents over the same evaluation period.", "During the exact same six-month evaluation period, the city also lowered the speed limit on those specific roads from 50 to 40 kilometres per hour and heavily increased police patrols.", "A comprehensive city budget audit revealed that the new LED streetlights consumed significantly less electricity than the older municipal streetlights they replaced.", "A sample survey of local motorists reported that the brighter LED light configurations occasionally caused uncomfortable glare when driving during rainy nighttime hours."], correctIndex: 1, level: 3, stimulus_type: "text", stimulus: {"text": "Passage: A city government recently installed bright LED streetlights along several major roads to reduce nighttime traffic accidents. In the six months following the installation, accident rates on those specific roads dropped by 18 percent. City officials concluded that the new lighting was directly responsible for the safety improvement and announced plans to immediately expand the costly LED programme to all remaining roads in the city, pointing out that better visibility allows drivers to spot hazards much earlier.", "evidence_spans": [{"text": "City officials concluded that the new lighting was directly responsible for the improvement and announced plans to expand the LED programme", "sentence_index": 2, "role": "establishes_claim"}], "external_knowledge_required": false, "cultural_specificity": "low", "structured_solution": "The city officials' argument relies entirely on a direct causal inference: the installation of LED streetlights caused the 18 percent drop in accidents. To weaken this argument, an option must introduce confounding variables that offer a powerful alternative explanation for the safety trend. Option B introduces two massive confounding changes implemented on those exact same roads at the exact same time: a lower speed limit and increased police patrols. This undercuts the officials' claim by making it highly probable that the regulatory and enforcement updates, rather than the lighting, drove the accident reduction. Option A strengthens the argument through external replication. Option C discusses energy efficiency, which is irrelevant to the safety metric. Option D details minor driver complaints but does not quantify any negative impact on actual crash data."} },
    { id: "gemini-code-1779397704494", prompt: "Which of the following, if true, most seriously undermines the transport authority's projection?", options: ["Electric transit buses require significantly more specialized technical maintenance over a five-year period than older diesel models.", "The three trial routes pass directly through dense industrial shipping zones where bus emissions account for a far larger share of total air pollution than on any other route in the city.", "Several other cities that adopted electric bus lines reported notable improvements in localized air quality indexes within the first year of deployment.", "The initial capital expense required to purchase a new electric bus fleet is currently higher than purchasing updated clean-diesel models of comparable carrying capacity."], correctIndex: 1, level: 3, stimulus_type: "text", stimulus: {"text": "Passage: A city transport authority recently replaced traditional diesel buses on three major routes with electric buses and reported a 15 percent drop in total air pollution levels along those coordinates over the following six months. Based on this localized success, the authority argues that replacing all diesel buses across the entire metropolitan network with electric buses would reduce citywide air pollution by a similar percentage, noting that electric options produce zero tailpipe emissions.", "evidence_spans": [{"text": "the authority argues that replacing all diesel buses across the entire city with electric buses would reduce citywide air pollution by a similar percentage", "sentence_index": 1, "role": "establishes_assumption"}], "external_knowledge_required": false, "cultural_specificity": "low", "structured_solution": "The transport authority performs a scope extrapolation error: they assume that the 15 percent pollution drop observed across a tiny, localized sample (three trial routes) will replicate uniformly when scaled citywide. Option B heavily undercuts this projection by demonstrating that the trial routes are completely unrepresentative of typical city conditions. If the trial coordinates pass through industrial zones where bus emissions dominate the pollution profile, a bus intervention will create a massive, atypical drop that cannot be expected on residential or commercial routes where other pollution sources dominate. Options A and D introduce financial and feasibility metrics, which are completely irrelevant to the core environmental logic model. Option C works in the opposite direction by strengthening the projection via external city comparison."} },
    { id: "gemini-code-1779397707711", prompt: "The city officials' cost-saving justification depends fundamentally on which of the following unstated assumptions?", options: ["The physical quality of light produced by municipal LED arrays is visually comparable to traditional sodium-vapour lighting.", "Any compounding public health or productivity costs resulting from widespread sleep disruption among residents will not exceed the financial savings generated by reduced energy use.", "The municipal tax base of the city is projected to grow significantly over the course of the next five fiscal quarters.", "Local taxpayers are primarily concerned with minimizing short-term municipal utility expenditure rather than addressing long-term lifestyle updates."], correctIndex: 1, level: 3, stimulus_type: "text", stimulus: {"text": "Passage: Many cities have begun replacing traditional streetlights with high-efficiency LED lights to reduce municipal energy consumption. LED options use up to 50 percent less electricity than conventional lamps and last significantly longer before requiring mechanical replacement, leading city officials to argue that the switch will ultimately save taxpayers money. However, some health advocates have raised concerns about the distinct bluish-white light emitted by LEDs, presenting clinical evidence that it severely disrupts human sleep patterns. Officials respond that the long-term financial savings fully justify the transition.", "evidence_spans": [{"text": "City officials argue that this switch will ultimately save taxpayers money.", "sentence_index": 2, "role": "establishes_claim"}, {"text": "some health advocates have raised concerns about the distinct bluish-white light emitted by LEDs, presenting clinical evidence that it severely disrupts human sleep patterns.", "sentence_index": 3, "role": "establishes_assumption"}], "external_knowledge_required": false, "cultural_specificity": "low", "structured_solution": "The city officials argue that the LED transition is financially justified because it will 'ultimately save taxpayers money.' This net financial benefit claim is valid only if the negative externalities introduced by the project do not generate new public costs that completely wipe out the utility savings. If the bluish-white light disrupts sleep patterns so severely that it results in massive medical costs, worker absenteeism, or lost economic productivity that exceeds the energy savings, then the project does not save taxpayers money overall. Therefore, the argument implicitly assumes that health-related costs will not exceed the operational savings. Option A is an aesthetic/functional point irrelevant to the financial equation. Option C introduces unrelated economic growth data. Option D confuses taxpayer motivations with the actual mathematical validity of the net cost-saving claim."} },
    { id: "gemini-code-1779397710944", prompt: "The passage argues that vertical farming could transform future agricultural models. Which of the following statements from the passage most directly supports the specific claim that vertical farming is uniquely suited to adapt to shifting global demographic distributions over the next few decades?", options: ["Unlike traditional agriculture, vertical farms operate year-round regardless of weather or season, producing multiple harvests annually from the same footprint.", "They also use up to ninety percent less water than field farms by recycling irrigation runoff in closed-loop systems.", "As urban populations are projected to reach nearly seventy percent of the global total by 2050, reducing dependence on distant rural farmland is increasingly seen as a strategic priority.", "Vertical farming has attracted significant investment in recent years from proponents who believe it could transform how modern populations are sustained."], correctIndex: 2, level: 3, stimulus_type: "text", stimulus: {"text": "Passage: Vertical farming - the practice of growing crops in stacked indoor layers - has attracted significant investment in recent years. Proponents argue it could transform how modern populations are sustained. Unlike traditional agriculture, vertical farms operate year-round regardless of weather or season, producing multiple harvests annually from the same footprint. They also use up to ninety percent less water than field farms by recycling irrigation runoff in closed-loop systems. Despite high energy costs, urban planners note that vertical farms can be built on small plots within city limits, drastically cutting transport distances. This spatial capability is critical; as urban populations are projected to reach nearly seventy percent of the global total by 2050, reducing dependence on distant rural farmland is increasingly seen as a strategic priority.", "evidence_spans": [{"text": "As urban populations are projected to reach nearly seventy percent of the global total by 2050, reducing dependence on distant rural farmland is increasingly seen as a strategic priority.", "sentence_index": 5, "role": "supports_correct_answer"}], "external_knowledge_required": false, "cultural_specificity": "low", "structured_solution": "The target claim specifies a very narrow parameter: adaptation to shifting global demographic distributions over the next few decades (which means changing where populations live over a future timeline). Sentence 6 directly addresses this parameter by referencing the explicit 2050 population projection-that 70 percent of the world will live in urban centers-and linking this trend to vertical farming's ability to reduce reliance on distant rural land. Options A and B describe powerful advantages of vertical farming (year-round output and water efficiency) but are general agricultural benefits that do not target demographic location shifts. Option D merely describes general investor investment and sentiment rather than empirical support for the specific demographic claim."} },
  ],
  mathematical_reasoning: [
    { id: "gemini-code-1779397069512", prompt: "Two whole numbers add up to 34. The larger number is 10 more than the smaller number. What is the smaller number?", options: ["10", "12", "17", "22"], correctIndex: 1, level: 1, stimulus_type: "text", stimulus: {"text": "A quantitative word problem outlining a two-variable system.", "expected_answer": "12", "structured_solution": "Smaller number = y; Larger number = y + 10. Equation: y + y + 10 = 34 -> 2y = 24 -> y = 12.", "uniqueness_check": "Exactly one answer choice is correct because the system of equations x + y = 34 and x - y = 10 has a unique deterministic point solution at (22, 12)."} },
    { id: "gemini-code-1779397222997", prompt: "Two independent mathematical rules run simultaneously at alternating positions in the progression below. What number logically replaces the question mark?\n\n5, 10, 8, 20, 11, 40, ?", options: ["80", "14", "13", "43"], correctIndex: 1, level: 1, stimulus_type: "text", stimulus: {"text": "An alternating numeric sequence containing seven terms.", "expected_answer": "14", "structured_solution": "Odd positions: 5, 8, 11 -> Rule is +3. Even positions: 10, 20, 40 -> Rule is x2. Position 7 is an odd term following 11, so 11 + 3 = 14.", "uniqueness_check": "Exactly one answer choice is correct because splitting the indexing coordinates mathematically isolates position 7 to a single linear arithmetic function."} },
    { id: "gemini-code-1779397323415", prompt: "Three positive integers a, b, and c each lie between 1 and 30 inclusive. Their product is 120, a is an even number, b is an odd number, and they follow the strict ordering a > b > c. What is the largest possible value of a?", options: ["10", "12", "20", "24"], correctIndex: 3, level: 2, stimulus_type: "text", stimulus: {"text": "A quantitative constraint word puzzle with restricted domain fields.", "expected_answer": "24", "structured_solution": "Minimize b * c subject to b odd, b > c >= 1, and 120/(b*c) <= 30. Try b=3, c=1 -> a=40 (invalid). Try b=5, c=1 -> a=24. Valid, since 24 is even and 24 > 5 > 1.", "uniqueness_check": "Exactly one answer choice is correct because any value of a > 24 requires b * c < 5, which has no odd-integer solution satisfying b > c >= 1 within the domain."} },
    { id: "gemini-code-1779397226682", prompt: "Three positive integers a, b, and c satisfy all of the following conditions:\n• a is exactly three times the value of c.\n• b is exactly 4 less than the value of a.\n• c is an odd number located strictly between 4 and 6.\n\nWhat is the value of b?", options: ["5", "9", "11", "15"], correctIndex: 2, level: 1, stimulus_type: "text", stimulus: {"text": "A quantitative constraint set mapping interdependencies between three integer variables.", "expected_answer": "11", "structured_solution": "Step 1: c is odd and 4 < c < 6 -> c = 5. Step 2: a = 3 * 5 = 15. Step 3: b = 15 - 4 = 11.", "uniqueness_check": "Exactly one answer choice is correct because the system resolves down a single, deterministic linear path with no branch variance."} },
    { id: "gemini-code-1779397334331", prompt: "Study the numeric sequence below to find the missing term marked by the question mark.\n\n2, 6, 14, 26, 42, ?", options: ["58", "60", "62", "66"], correctIndex: 2, level: 2, stimulus_type: "text", stimulus: {"text": "A progressive sequence of six integers displaying an accelerating growth rate.", "expected_answer": "62", "structured_solution": "First differences: 4, 8, 12, 16. Second differences: 4, 4, 4 (constant). Next first difference = 16 + 4 = 20. Next term = 42 + 20 = 62.", "uniqueness_check": "Exactly one answer choice is correct because a constant second difference defines a unique quadratic polynomial, $f(n) = 2n^2 - 2n + 2$, which evaluates to 62 at $n = 6$."} },
    { id: "gemini-code-1779397072513", prompt: "In a village trading network, 3 sacks of rice can be exchanged for exactly 4 baskets of potatoes, and 5 baskets of potatoes can be exchanged for exactly 6 crates of tomatoes. How many sacks of rice are required to secure 48 crates of tomatoes?", options: ["24", "30", "36", "40"], correctIndex: 1, level: 1, stimulus_type: "text", stimulus: {"text": "A word problem tracking three interdependent variables across two discrete exchange rates.", "expected_answer": "30", "structured_solution": "Step 1: Potatoes needed = 48 * (5/6) = 40 baskets. Step 2: Rice needed = 40 * (3/4) = 30 sacks.", "uniqueness_check": "Exactly one answer choice is correct because tracking the direct linear composition function f(x) = x * (5/6) * (3/4) maps 48 uniquely to 30."} },
    { id: "gemini-code-1779397338029", prompt: "For any positive integer $n \\ge 2$, compare the two quantities below to select the correct relationship.", options: ["Quantity A is greater than Quantity B", "Quantity A is less than Quantity B", "Quantity A is equal to Quantity B", "The relationship cannot be determined from the given information"], correctIndex: 0, level: 2, stimulus_type: "text", stimulus: {"text": "Quantity A: $\\frac{n^2 - 1}{n^2 + 1}$\n\nQuantity B: $\\frac{n - 1}{n}$", "expected_answer": "Quantity A is greater than Quantity B", "structured_solution": "Cross-multiply: n(n^2 - 1) vs (n - 1)(n^2 + 1) -> n^3 - n vs n^3 - n^2 + n - 1. Difference: (n^3 - n) - (n^3 - n^2 + n - 1) = n^2 - 2n + 1 = (n - 1)^2. For n >= 2, (n - 1)^2 > 0, so A > B.", "uniqueness_check": "Exactly one answer choice is correct because the difference simplifies to a perfect square that is strictly greater than zero for all real numbers where n > 1."} },
    { id: "gemini-code-1779397218732", prompt: "Compare Quantity A and Quantity B based on the expressions below.", options: ["Quantity A is greater than Quantity B", "Quantity A is less than Quantity B", "Quantity A is equal to Quantity B", "The relationship cannot be determined from the given information"], correctIndex: 1, level: 1, stimulus_type: "text", stimulus: {"text": "Quantity A: Half of 90\nQuantity B: One-third of 150", "expected_answer": "Quantity A is less than Quantity B", "structured_solution": "Quantity A = 90 / 2 = 45. Quantity B = 150 / 3 = 50. Since 45 < 50, A < B.", "uniqueness_check": "Exactly one answer choice is correct because the resolved whole numbers 45 and 50 maintain a strict inequality relationship."} },
    { id: "gemini-code-1779397214134", prompt: "Based on the sales table below, which fruit had the greatest absolute difference in sales volume between Week 1 and Week 2?", options: ["Mangoes", "Bananas", "Apples", "Mangoes and Bananas are tied"], correctIndex: 0, level: 1, stimulus_type: "text", stimulus: {"text": "Data Table:\n| Fruit | Week 1 sales (kg) | Week 2 sales (kg) |\n|---|---|---|\n| Mangoes | 45 | 60 |\n| Apples | 30 | 25 |\n| Bananas | 50 | 40 |", "expected_answer": "Mangoes", "structured_solution": "Mangoes difference = |60 - 45| = 15. Apples difference = |25 - 30| = 5. Bananas difference = |40 - 50| = 10. Max(15, 5, 10) = 15, corresponding to Mangoes.", "uniqueness_check": "Exactly one answer choice is correct because the absolute differences evaluates to a unique maximum value of 15 kg."} },
    { id: "gemini-code-1779397331246", prompt: "An original solution is exactly 40% acid by weight. First, a certain amount of pure water is added, which dilutes the acid concentration down to 25%. Next, a certain amount of pure acid is added, which raises the total concentration up to 50%. If this final mixture weighs exactly 24 kg, what was the weight of the original solution?", options: ["8 kg", "10 kg", "12 kg", "15 kg"], correctIndex: 1, level: 2, stimulus_type: "text", stimulus: {"text": "A multi-stage chemical mixture problem tracking absolute mass transformations.", "expected_answer": "10 kg", "structured_solution": "Acid mass = 0.4W. Post-water total = 0.4W/0.25 = 1.6W. Post-acid addition A: (0.4W + A)/(1.6W + A) = 0.5 -> A = 0.8W. Total final weight = 2.4W = 24 kg -> W = 10 kg.", "uniqueness_check": "Exactly one answer choice is correct because setting up the conservation system bounds the initial value to a singular linear dependency path."} },
    { id: "gemini-code-1779397327496", prompt: "A container holds a mixture of liquid chemical and pure water in the ratio 3:2. If 10 litres of the mixture is removed and replaced with 10 litres of pure water, the new ratio of chemical to water becomes 1:1. What is the total volume of the mixture in litres?", options: ["30", "40", "50", "60"], correctIndex: 3, level: 2, stimulus_type: "text", stimulus: {"text": "A multi-stage fluid replacement word scenario involving concentration changes.", "expected_answer": "60", "structured_solution": "Initial: C = 0.6V, W = 0.4V. Removal of 10L removes 6L of C and 4L of W. Addition of 10L water makes final W = 0.4V + 6. Equation: 0.6V - 6 = 0.4V + 6 -> 0.2V = 12 -> V = 60.", "uniqueness_check": "Exactly one answer choice is correct because the linear mass balance equation has a single valid root over the set of positive real numbers."} },
    { id: "gemini-code-1779397075428", prompt: "A box contains exactly 100 red tokens and 100 blue tokens. A student plays a game where they remove exactly two tokens from the box at each step and apply the following transformation rules:\n1. If the two removed tokens are the same color, they are discarded, and 1 red token is added back into the box.\n2. If the two removed tokens are different colors, the red token is discarded, and 1 blue token is added back into the box.\n\nThis process is repeated systematically until only one single token remains in the box. Which statement regarding the color of the final token must always be true?", options: ["The final token must always be Red.", "The final token must always be Blue.", "The final token can be either color depending on the order of removals.", "The final token will match whichever color was removed most frequently during the first fifty steps."], correctIndex: 0, level: 2, stimulus_type: "text", stimulus: {"text": "A finite token-manipulation system governed by operational state-change rules.", "expected_answer": "The final token must always be Red.", "structured_solution": "Blue token transitions are either -2 or 0 per step. Initial Blue = 100 (even). Therefore, Blue count must always remain even. Total tokens decrease by 1 per step, ending at 1. Since Blue must be even, Blue = 0, meaning the final token must be Red.", "uniqueness_check": "Exactly one answer choice is correct because the parity invariant mathematical law rigorously proves that it is impossible to finish the system state at Blue = 1 when starting from an even coordinate."} },
    { id: "gemini-code-1779397231314", prompt: "A bakery uses exactly 5 cups of flour to produce 3 whole loaves of bread. Each finished loaf of bread is then sliced into exactly 8 equal pieces. How many individual pieces of bread can be made from 20 cups of flour?", options: ["12", "32", "48", "96"], correctIndex: 3, level: 1, stimulus_type: "text", stimulus: {"text": "A multi-stage production rate scenario mapping raw material input to a segmented finished commodity.", "expected_answer": "96", "structured_solution": "Step 1: Loaves produced = (20 / 5) * 3 = 12 loaves. Step 2: Total pieces = 12 * 8 = 96 pieces.", "uniqueness_check": "Exactly one answer choice is correct because the composite linear scale factor f(x) = x * (3/5) * 8 yields a unique output of 96 for x = 20."} },
  ],
};

export function isPreviewSampleExamId(examId: string): examId is PreviewSampleExamId {
  return (PREVIEW_SAMPLE_EXAM_IDS as readonly string[]).includes(examId);
}

export function getPreviewSampleQuestions(examId: string, level?: PreviewSampleLevel): PreviewSampleQuestion[] {
  const questions = isPreviewSampleExamId(examId)
    ? PREVIEW_SAMPLE_QUESTIONS_BY_EXAM[examId]
    : PREVIEW_SAMPLE_QUESTIONS_BY_EXAM[DEFAULT_PREVIEW_SAMPLE_EXAM_ID];
  return level == null ? questions : questions.filter((q) => q.level === level);
}

export function getPreviewSampleQuestionCount(examId: string, level?: PreviewSampleLevel): number {
  return getPreviewSampleQuestions(examId, level).length;
}

export function getPreviewSampleAssessmentPath(examId: string): string {
  const resolved = isPreviewSampleExamId(examId) ? examId : DEFAULT_PREVIEW_SAMPLE_EXAM_ID;
  return `/for-schools/preview/assessment/${resolved}`;
}

export const PREVIEW_SAMPLE_ASSESSMENT_BASE_PATH = '/for-schools/preview/assessment';
